begin;
do $$
declare owner_id uuid; guest_id uuid; outsider uuid:=gen_random_uuid(); g uuid:=gen_random_uuid(); t uuid:=gen_random_uuid(); m uuid:=gen_random_uuid(); state jsonb; food jsonb; cid uuid; other_cid uuid; item uuid; extra uuid; rev bigint; before_snapshot jsonb;
begin
 select id into owner_id from auth.users where email_confirmed_at is not null and not coalesce(is_anonymous,false) order by created_at limit 1;
 select id into guest_id from auth.users where email_confirmed_at is not null and not coalesce(is_anonymous,false) and id<>owner_id order by created_at limit 1;
 if guest_id is null then raise exception 'two confirmed fixtures required';end if;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 insert into public.travel_groups(id,owner_id,name) values(g,owner_id,'Companion rollback fixture');
 insert into public.trips(id,group_id,organizer_id,name,event_type) values(t,g,owner_id,'Companion rollback fixture','celebration');
 insert into public.trip_access(trip_id,profile_id,role,granted_by) values(t,owner_id,'organizer',owner_id),(t,guest_id,'participant',owner_id);
 insert into public.group_members(id,group_id,display_name,created_by) values(m,g,'Guest fixture',owner_id);
 insert into public.trip_participants(trip_id,member_id,local_source_id) values(t,m,'guest');
 insert into public.member_profile_links(member_id,profile_id,status,authorized_by) values(m,guest_id,'active',owner_id);
 before_snapshot:='{"trip":{"eventType":"event","potluckMode":"potluck"},"payments":[{"amountCents":12345}],"people":[{"id":"guest","contributes":true}]}';
 insert into public.trip_snapshots(trip_id,payload,revision,updated_by) values(t,before_snapshot,1,owner_id);
 state:=public.get_event_companions(t);
 if not (state->>'enabled')::boolean or not (state->>'allowed')::boolean then raise exception 'default event companions missing';end if;
 state:=public.change_event_companions(t,'settings','{"allowed":true,"limit":1}',1);
 perform set_config('request.jwt.claim.sub',guest_id::text,true);
 state:=public.change_event_companions(t,'save',jsonb_build_object('name','Ana','kind','adult','responsible_id',owner_id),0);
 cid:=(state->'items'->0->>'id')::uuid;
 if not exists(select 1 from public.event_companions where id=cid and responsible_id=guest_id) then raise exception 'responsible spoof allowed';end if;
 begin perform public.change_event_companions(t,'save','{"name":"Outra","kind":"child"}',0);raise exception 'limit ignored';exception when others then if sqlerrm<>'companion limit' then raise;end if;end;
 begin perform public.change_event_companions(t,'settings','{"allowed":false,"limit":0}',2);raise exception 'guest changed settings';exception when others then if sqlerrm<>'access denied' then raise;end if;end;
 begin perform public.change_event_companions(t,'save',jsonb_build_object('id',cid,'name','Ana','kind','child'),0);raise exception 'stale update accepted';exception when others then if sqlerrm<>'companions changed' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 food:=public.change_event_potluck(t,'item','{"name":"Salpicão","category":"Acompanhamentos","quantity":2,"unit":"travessas"}',1);
 item:=(food->'items'->0->>'id')::uuid;rev:=(food->>'revision')::bigint;
 perform set_config('request.jwt.claim.sub',guest_id::text,true);
 food:=public.change_event_potluck(t,'claim',jsonb_build_object('item_id',item,'quantity',1,'scope','family','label','Spoof','companion_id',cid),rev);
 if food->'items'->0->'claims'->0->>'label'<>'Ana' or (food->'items'->0->'claims'->0->>'companion_id')::uuid<>cid then raise exception 'companion dish not assigned';end if;
 rev:=(food->>'revision')::bigint;
 food:=public.change_event_potluck(t,'extra',jsonb_build_object('name','Pudim','category','Sobremesas','quantity',1,'unit','formas','scope','person','companion_id',cid),rev);
 select id into extra from public.event_potluck_items where trip_id=t and name='Pudim';
 if not exists(select 1 from public.event_potluck_claims where item_id=extra and companion_id=cid) then raise exception 'extra companion lost';end if;
 begin perform public.change_event_companions(t,'remove',jsonb_build_object('id',cid),1);raise exception 'dish companion removed';exception when others then if sqlerrm<>'companion has dishes' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 state:=public.change_event_companions(t,'save',jsonb_build_object('id',cid,'name','Ana Maria','kind','adult'),1);
 if exists(select 1 from public.event_potluck_claims where companion_id=cid and label<>'Ana Maria') then raise exception 'renamed dish stale';end if;
 state:=public.change_event_companions(t,'settings','{"allowed":false,"limit":0}',2);
 perform set_config('request.jwt.claim.sub',guest_id::text,true);
 begin perform public.change_event_companions(t,'save','{"name":"Outra","kind":"child"}',0);raise exception 'disabled additions allowed';exception when others then if sqlerrm<>'companions disabled' then raise;end if;end;
 state:=public.change_event_companions(t,'save',jsonb_build_object('id',cid,'name','Ana Maria','kind','child'),2);
 if state->'items'->0->>'kind'<>'child' then raise exception 'existing edit blocked';end if;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 state:=public.change_event_companions(t,'settings','{"allowed":true,"limit":2}',3);
 state:=public.change_event_companions(t,'save','{"name":"Owner companion","kind":"adult"}',0);
 select id into other_cid from public.event_companions where trip_id=t and responsible_id=owner_id;
 perform set_config('request.jwt.claim.sub',guest_id::text,true);
 begin perform public.change_event_companions(t,'save',jsonb_build_object('id',other_cid,'name','Spoof','kind','adult'),1);raise exception 'foreign edit accepted';exception when others then if sqlerrm<>'access denied' then raise;end if;end;
 begin perform public.change_event_companions(t,'remove',jsonb_build_object('id',other_cid),1);raise exception 'foreign delete accepted';exception when others then if sqlerrm<>'access denied' then raise;end if;end;
 select revision into rev from public.event_potluck_settings where trip_id=t;
 begin perform public.change_event_potluck(t,'claim',jsonb_build_object('item_id',item,'quantity',1,'scope','person','companion_id',other_cid),rev);raise exception 'foreign dish assignment accepted';exception when others then if sqlerrm<>'access denied' then raise;end if;end;
 begin perform public.change_event_companions(t,'save','{"name":"Ana Maria","kind":"adult"}',0);raise exception 'duplicate accepted';exception when unique_violation then null;end;
 perform set_config('request.jwt.claim.sub',outsider::text,true);
 begin perform public.get_event_companions(t);raise exception 'outsider read';exception when others then if sqlerrm<>'access denied' then raise;end if;end;
 begin perform public.change_event_companions(t,'remove',jsonb_build_object('id',cid),3);raise exception 'outsider write';exception when others then if sqlerrm<>'access denied' then raise;end if;end;
 perform set_config('request.jwt.claim.sub','',true);
 begin perform public.get_event_companions(t);raise exception 'anonymous read';exception when others then if sqlerrm<>'access denied' then raise;end if;end;
 if (select payload->'payments' from public.trip_snapshots where trip_id=t) is distinct from before_snapshot->'payments' then raise exception 'financial snapshot altered';end if;
 if exists(select 1 from public.event_companions where trip_id=t and participant_id is null) then raise exception 'canonical participant missing';end if;
 if has_table_privilege('authenticated','public.event_companions','INSERT') or has_function_privilege('anon','public.change_event_companions(uuid,text,jsonb,bigint)','EXECUTE') or has_function_privilege('authenticated','public.change_event_potluck_without_companions(uuid,text,jsonb,bigint)','EXECUTE') then raise exception 'bypass API exposed';end if;
end $$;
rollback;
